inline ChildRecord& ChildRecord::updatePlatform(const Platform& value) {
    platform_ = detail::make_box<Platform>(memory_resource(), value);
    updatePlatformId(value.id());
    return *this;
}

inline const Platform* Holder::platform() const {
    if (platform_) {
        return platform_.get();
    }
    if (!is_loaded("platform")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<Platform>("holder", id(), "platform");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<Platform>(platformId());
}

inline const Record* Holder::record() const {
    if (record_) {
        return record_.get();
    }
    if (!is_loaded("record")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<Record>("holder", id(), "record");
    if (view) {
        return *view ? &**view : nullptr;
    }
    auto foreign = recordId();
    return foreign ? root.resolve_entity<Record>(*foreign) : nullptr;
}

inline eval::EvalResult<EntityBorrow<Platform>> Holder::evalPlatform() const {
    return GeneratedRelationAccess::object(memory_resource(), "platform", platform(), false);
}

inline eval::EvalResult<EntityBorrow<Record>> Holder::evalRecord() const {
    return GeneratedRelationAccess::object(
        memory_resource(), "record", record(), is_loaded("record_id") && !recordId());
}

inline std::optional<Json> Holder::borrowed_json(Memory r, EntityJsonTraversal& traversal) const {
    GeneratedEntityJson projection(r, traversal, ENTITY_NAME, this, root, id_for_runtime());
    projection.field(
        "id",
        [&] {
            return generated_detail::encode(r, id_);
        },
        load_state.is_loaded("id"),
        true);
    projection.field(
        "platform_id",
        [&] {
            return generated_detail::encode(r, platform_id_);
        },
        load_state.is_loaded("platform_id"),
        false);
    projection.field(
        "name",
        [&] {
            return generated_detail::encode(r, name_);
        },
        load_state.is_loaded("name"),
        false);
    projection.field(
        "record_id",
        [&] {
            return generated_detail::encode(r, record_id_);
        },
        load_state.is_loaded("record_id"),
        false);
    projection.field(
        "version",
        [&] {
            return generated_detail::encode(r, version_);
        },
        load_state.is_loaded("version"),
        true);
    projection.dynamic(dynamic);
    projection.forward<Platform>("platform",
                                 platform_ ? &*platform_ : nullptr,
                                 load_state.is_loaded("platform"),
                                 generated_detail::encode(r, platform_id_));
    projection.forward<Record>("record",
                               record_ ? &*record_ : nullptr,
                               load_state.is_loaded("record"),
                               generated_detail::encode(r, record_id_));
    return projection.finish(dynamic_field_values());
}

inline void Holder::attachRuntimeStateRecursive(const EntityRuntimeState& target) {
    root.attach_runtime_state(target);
    if (platform_) {
        platform_->attachRuntimeStateRecursive(target);
    }
    if (record_) {
        record_->attachRuntimeStateRecursive(target);
    }
}

